        foreach (var ajeno in new[] { "Laura Gómez", "Andrés Martínez", "Sofía Herrera", "EST-001", "EST-002", "EST-003" })
        {
            Assert.DoesNotContain(ajeno, enviado, StringComparison.Ordinal);
        }
    }

